t.script:
function sanitize(val) {
    if (!val) return '';
    return val.replace(/[<>"'`;]/g, '');
}

function parseJson(id, fallback) {
    var node = document.getElementById(id);
    if (!node) return fallback;
    try { return JSON.parse(node.textContent); } catch (e) { return fallback; }
}

document.addEventListener('DOMContentLoaded', function() {
    // Fecha máxima = hoy
    var today = new Date().toISOString().split('T')[0];
    var fechaInp = document.getElementById('fecha_inscripcion');
    if (fechaInp) fechaInp.setAttribute('max', today);

    var coursesByTcu = parseJson('ets-courses-json', {});
    var tcuDisable = parseJson('ets-tcu-disable-json', []);
    var tcuNotes = parseJson('ets-tcu-notes-json', {});
    var tcuSel = document.getElementById('tcu_confirm');
    var carrera = document.getElementById('carrera_confirm');
    var otroWrap = document.getElementById('campo_curso_otro_confirm');
    var nota = document.getElementById('nota_carrera_confirm');
    var carreraInicial = carrera ? (carrera.getAttribute('data-inicial') || '') : '';

    function fillCarreras(tcu, keepInicial) {
        if (!carrera) return;
        carrera.innerHTML = '';
        var disabled = !tcu || tcuDisable.indexOf(tcu) !== -1;
        var opts = coursesByTcu[tcu] || [];
        var first = document.createElement('option');
        first.value = '';
        if (disabled) {
            first.textContent = tcu ? 'No aplica para año académico' : 'Seleccione primero el TSU...';
            carrera.appendChild(first);
            carrera.disabled = true;
            carrera.value = '';
        } else {
            first.textContent = 'Seleccione...';
            carrera.appendChild(first);
            opts.forEach(function (pair) {
                var o = document.createElement('option');
                o.value = pair[0];
                o.textContent = pair[1];
                carrera.appendChild(o);
            });
            carrera.disabled = false;
            if (keepInicial && carreraInicial) carrera.value = carreraInicial;
        }
        if (nota) {
            var msg = tcuNotes[tcu] || '';
            nota.textContent = msg;
            nota.classList.toggle('d-none', !msg);
        }
        if (otroWrap) {
            otroWrap.classList.toggle('d-none', carrera.value !== 'Otras');
        }
    }

    if (tcuSel && carrera) {
        tcuSel.addEventListener('change', function () { fillCarreras(this.value, false); });
        fillCarreras(tcuSel.value, true);
        carrera.addEventListener('change', function () {
            if (otroWrap) otroWrap.classList.toggle('d-none', this.value !== 'Otras');
        });
    }

    var munByDept = parseJson('ets-municipios-json', {});
    var deptSel = document.getElementById('departamento');
    var munSel = document.getElementById('municipio');
    if (deptSel && munSel) {
        Object.keys(munByDept).sort().forEach(function (dept) {
            var o = document.createElement('option');
            o.value = dept;
            o.textContent = dept;
            deptSel.appendChild(o);
        });
        deptSel.addEventListener('change', function () {
            var list = munByDept[this.value] || [];
            munSel.innerHTML = '';
            var first = document.createElement('option');
            first.value = '';
            if (!this.value) {
                first.textContent = 'Seleccione primero el departamento...';
                munSel.appendChild(first);
                munSel.disabled = true;
                return;
            }
            first.textContent = 'Seleccione...';
            munSel.appendChild(first);
            list.forEach(function (name) {
                var o = document.createElement('option');
                o.value = name;
                o.textContent = name;
                munSel.appendChild(o);
            });
            munSel.disabled = false;
        });
    }

    // Sanitizar al enviar
    var form = document.getElementById('inscripcion-form');
    if (form) {
        form.addEventListener('submit', function() {
            var inputs = this.querySelectorAll('input[type=text], textarea');
            inputs.forEach(function(inp) { inp.value = sanitize(inp.value); });
        });
    }

    // Validar teléfono: solo números
    var tel = document.getElementById('telefono');
    if (tel) tel.addEventListener('input', function() {
        this.value = this.value.replace(/[^0-9]/g, '').slice(0, 8);
    });

    // CUI: solo números 13 dígitos
    var cui = document.getElementById('cui');
    if (cui) cui.addEventListener('input', function() {
        this.value = this.value.replace(/[^0-9]/g, '').slice(0, 13);
    });

    // Teléfono empresa
    var telEmp = document.getElementById('telefono_empresa');
    if (telEmp) telEmp.addEventListener('input', function() {
        this.value = this.value.replace(/[^0-9]/g, '').slice(0, 8);
    });

    // NIT: números y K
    var nit = document.getElementById('nit');
    if (nit) nit.addEventListener('input', function() {
        this.value = this.value.replace(/[^0-9kK]/g, '').toUpperCase();
    });

    // Carné: alfanumérico
    var carne = document.getElementById('carne');
    if (carne) carne.addEventListener('input', function() {
        this.value = this.value.replace(/[^a-zA-Z0-9]/g, '');
    });

    // DPI: solo números 13 dígitos
    var dpi = document.getElementById('dpi');
    if (dpi) dpi.addEventListener('input', function() {
        this.value = this.value.replace(/[^0-9]/g, '').slice(0, 13);
        verificarCondiciones();
    });

    // Checkbox condiciones
    var chk = document.getElementById('acepta_condiciones');
    if (chk) chk.addEventListener('change', verificarCondiciones);
});

function verificarCondiciones() {
    var chk = document.getElementById('acepta_condiciones');
    var nombre = document.getElementById('nombre_alumno');
    var dpi = document.getElementById('dpi');
    var fecha = document.getElementById('fecha_inscripcion');
    var btn = document.getElementById('btn_enviar');
    if (chk && nombre && dpi && fecha && btn) {
        if (chk.checked && nombre.value.trim().length > 0 && dpi.value.length === 13 && fecha.value) {
            btn.removeAttribute('disabled');
        } else {
            btn.setAttribute('disabled', '1');
        }
    }
}

function nextStep(current) {
    if (current === 1) {
        var tel = document.getElementById('telefono');
        if (!tel.value || tel.value.length !== 8) {
            alert('El teléfono debe tener exactamente 8 dígitos.');
            return;
        }
        var cui = document.getElementById('cui');
        if (!cui.value || cui.value.length !== 13) {
            alert('El CUI debe tener exactamente 13 dígitos.');
            return;
        }
        var whatsapp = document.querySelector('input[name=whatsapp]:checked');
        if (!whatsapp) { alert('Por favor indique si tiene WhatsApp.'); return; }
        var jornada = document.querySelector('input[name=jornada]:checked');
        if (!jornada) { alert('Por favor seleccione una jornada.'); return; }
        var tcuSel = document.getElementById('tcu_confirm');
        if (!tcuSel || !tcuSel.value) { alert('Por favor confirme el Técnico Superior Universitario.'); return; }
        var carreraSel = document.getElementById('carrera_confirm');
        var tcuDisable = parseJson('ets-tcu-disable-json', []);
        var tcuAnioAcad = tcuDisable.indexOf(tcuSel.value) !== -1;
        if (!tcuAnioAcad) {
            if (!carreraSel || !carreraSel.value) { alert('Por favor confirme el curso o carrera técnica.'); return; }
            if (carreraSel.value === 'Otras') {
                var otro = document.getElementById('curso_otro_confirm');
                if (!otro || !otro.value.trim()) { alert('Por favor especifique el curso.'); return; }
            }
        }
    }
    if (current === 2) {

        var edad = document.querySelector('input[name=edad]:checked');
        if (!edad) { alert('Por favor seleccione si es menor o mayor de edad.'); return; }
        var genero = document.querySelector('input[name=genero]:checked');
        if (!genero) { alert('Por favor seleccione su género.'); return; }
        var alumno = document.querySelector('input[name=alumno]:checked');
        if (!alumno) { alert('Por favor seleccione si es primer ingreso o reingreso.'); return; }
        var dpto = document.getElementById('departamento');
        if (!dpto || !dpto.value) { alert('Por favor seleccione su departamento.'); return; }
        var mun = document.getElementById('municipio');
        if (!mun || !mun.value) { alert('Por favor seleccione su municipio.'); return; }
        var entero = document.querySelector('select[name=como_se_entero]');
        if (!entero.value) { alert('Por favor indique cómo se enteró de Kinal.'); return; }
        var grado = document.querySelector('input[name=ultimo_grado]');
        if (!grado.value.trim()) { alert('Por favor ingrese su último grado aprobado.'); return; }
    }
    document.getElementById('step-' + current).classList.add('d-none');
    document.getElementById('step-' + (current + 1)).classList.remove('d-none');
    updateIndicators(current + 1);
    window.scrollTo(0, 0);
}

function prevStep(current) {
    document.getElementById('step-' + current).classList.add('d-none');
    document.getElementById('step-' + (current - 1)).classList.remove('d-none');
    updateIndicators(current - 1);
    window.scrollTo(0, 0);
}

function updateIndicators(active) {
    for (var i = 1; i <= 4; i++) {
        var circle = document.querySelector('#ind-' + i + ' div');
        circle.style.background = (i === active) ? '#195190' : '#ccc';
    }
}

function actualizarEdad(val) {
    val = parseInt(val);
    if (!isNaN(val)) {
        document.getElementById('edad_menor').disabled = val >= 18;
        document.getElementById('edad_mayor').disabled = val < 18;
        if (val >= 18) {
            document.getElementById('edad_mayor').checked = true;
        } else {
            document.getElementById('edad_menor').checked = true;
        }
    }
}

function toggleCarne(show) {
    document.getElementById('campo_carne').classList.toggle('d-none', !show);
}

function toggleRecomendante(val) {
    var showNombre = ['compañero_trabajo', 'familiar', 'conocido'].includes(val);
    var showParentesco = val === 'familiar';
    document.getElementById('campo_recomendante').classList.toggle('d-none', !showNombre);
    document.getElementById('campo_parentesco').classList.toggle('d-none', !showParentesco);
}

function toggleVehiculo(show) {
    document.getElementById('campo_vehiculo').classList.toggle('d-none', !show);
}
